


-- Handbook v1.14 remediation: retain a dense synthetic offer market while removing candidate labels
-- and recording distinct connection/refund constraints. Official change-rule anchors remain external.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'Hangzhou Easttranslated business text' WHEN 1 THEN 'translated business text' WHEN 2 THEN 'translated business text' WHEN 3 THEN 'translated business text'
      WHEN 4 THEN 'Nanjing Southterminal arrival' WHEN 5 THEN 'translated business textdeparture' WHEN 6 THEN 'translated business textarrival' WHEN 7 THEN 'translated business textarrival'
      WHEN 8 THEN 'translated business textseatremaining quantitytranslated business text' WHEN 9 THEN 'translated business textticketremaining quantitytranslated business text' WHEN 10 THEN 'translated business textavailable' WHEN 11 THEN 'stationtranslated business text'
      WHEN 12 THEN 'translated business text' WHEN 13 THEN 'translated business text' WHEN 14 THEN 'translated business textandmetroshuttle' WHEN 15 THEN 'tostationafterstill needsbeforetranslated business textexam site'
      ELSE 'translated business textpersontickettranslated business text' END AS route_fact,
    CASE rowid % 19
      WHEN 0 THEN 'departurebeforetranslated business textrulestranslated business textticket' WHEN 1 THEN 'change tickettranslated business texthasremaining seats' WHEN 2 THEN 'departureafterrulestranslated business text' WHEN 3 THEN 'does not automaticallyticketing'
      WHEN 4 THEN 'does not automaticallychange ticket' WHEN 5 THEN 'not yettranslated business textpurchaseauthorization' WHEN 6 THEN 'tickettranslated business textmayupdate' WHEN 7 THEN 'remaining seatsmaychange'
      WHEN 8 THEN 'translated business textverifytranslated business textdate' WHEN 9 THEN 'translated business textverifytostationtranslated business text' WHEN 10 THEN 'translated business textretainexam sitetranslated business textbuffer' WHEN 11 THEN 'withouthotelbooking'
      WHEN 12 THEN 'withouttranslated business textservice' WHEN 13 THEN 'sourceforsyntheticquerytranslated business text' WHEN 14 THEN 'executebeforetranslated business textsearch' WHEN 15 THEN 'translated business textroutetranslated business text'
      WHEN 16 THEN 'translated business textandtranslated business text' WHEN 17 THEN 'canceltranslated business textrulestranslated business text' ELSE 'statusaccording totranslated business textqueryprevails' END AS rule_fact
  FROM train_offers WHERE offer_id LIKE 'RAIL_HZ_NJ_DIST_%'
)
UPDATE train_offers
SET route_notes=CASE rowid % 7
      WHEN 0 THEN (SELECT route_fact || '；' || rule_fact || '。' FROM facts WHERE facts.rid=train_offers.rowid)
      WHEN 1 THEN (SELECT 'translated business text：' || route_fact || '。rulesboundary：' || rule_fact || '。' FROM facts WHERE facts.rid=train_offers.rowid)
      WHEN 2 THEN (SELECT rule_fact || '；translated business text' || route_fact || '。' FROM facts WHERE facts.rid=train_offers.rowid)
      WHEN 3 THEN (SELECT 'routetranslated business textfor' || route_fact || '，translated business textbeforetranslated business text' || rule_fact || '。' FROM facts WHERE facts.rid=train_offers.rowid)
      WHEN 4 THEN (SELECT route_fact || '，translated business textforsimilartranslated business text；' || rule_fact || '。' FROM facts WHERE facts.rid=train_offers.rowid)
      WHEN 5 THEN (SELECT 'synthetictranslated business textroadquoterecord：' || route_fact || '；' || rule_fact || '。' FROM facts WHERE facts.rid=train_offers.rowid)
      ELSE (SELECT 'querytranslated business text' || route_fact || '。aftertranslated business textis' || rule_fact || '。' FROM facts WHERE facts.rid=train_offers.rowid)
    END,
    source_url='https://rail.example.test/offers/' || lower(train_no) || '/' || replace(date,'-',''),
    offer_id=replace(offer_id,'RAIL_HZ_NJ_DIST_','RAIL_HZ_NJ_OPTION_')
WHERE offer_id LIKE 'RAIL_HZ_NJ_DIST_%';

-- Seat/status freshness is historical at t=0; release-005 carries the later
-- seat-count change for the selected offer.
UPDATE train_status
SET last_updated = '2026-08-01T08:00:00+08:00'
WHERE last_updated > '2026-08-01T09:00:00+08:00';
